// Read-only 0.8 reference gate shared by native CTest and native/WASM CI.
// Reference bytes are never regenerated by this runner. Fuel is deliberately
// excluded: the 0.9 tariff applies to old programs too.
"use strict";

const assert = require("node:assert/strict");
const {execFileSync, spawnSync} = require("node:child_process");
const {createHash} = require("node:crypto");
const fs = require("node:fs");
const path = require("node:path");
const {decodePng} = require("./png.js");
const {replaceFloatConstants} = require("./vector-conformance.js");

const repo = path.resolve(__dirname, "../../..");
const fixturePath = path.join(repo, "tests/fixtures/compat-v0.8.json");
const sha = data => createHash("sha256").update(data).digest("hex");

function noiseSource(vectors, form) {
    const constant = form.startsWith("constant");
    const declarations = constant ? vectors.map((v, i) =>
        `const f32 n${i} = ${form === "constant-vector" ? v.vector : v.scalar}`).join("\n") : "";
    const body = vectors.map((v, i) => {
        const call = form === "vector" ? v.vector : v.scalar;
        // A uniform, even with default zero, prevents optimizer folding. The
        // constant form deliberately exercises the compiler evaluator instead.
        const expression = constant ? `n${i}` : call.replace(/, (-?\d+)\)$/, ", ($1 + runtime_seed))");
        return `values = {${expression}, 0.0}`;
    }).join("\n");
    return `asset FrozenNoise { size 1x1 output list point values output point state
      ${constant ? "" : "input i32 runtime_seed=0"}
      ${declarations}
      draw { before=seed ${body} state={seed==before,unit()} } }\n`;
}

function native(tool, file, options, directory) {
    const png = path.join(directory, "compat.png");
    const args = [file, "--float-bits", "--seed", String(options.seed), "-o", png];
    if (options.sizeX) args.push("--size", `${options.sizeX}x${options.sizeY}`);
    for (const [name, value] of Object.entries(options.uniforms || {}))
        args.push("--uniform", `${name}=${value}`);
    const result = JSON.parse(execFileSync(tool("ipgen"), args, {encoding: "utf8"}));
    const image = decodePng(fs.readFileSync(png));
    return {width: image.width, height: image.height, rgba_sha256: sha(image.data), outputs: result.outputs};
}

function wasm(iprop, bytes, options) {
    const result = iprop.generate(new Uint8Array(bytes), options);
    return {width: result.width, height: result.height, rgba_sha256: sha(result.data),
        outputs: result.outputs.map(o => ({name: o.name, kind: ["point", "rect", "circle"][o.kind],
            list: o.isList, values: o.valueBits}))};
}

function compile(tool, source, file, optimize, debug, compress) {
    execFileSync(tool("ipc"), [source, "-o", file, ...(optimize ? [] : ["--no-opt"]),
        debug ? "--debug" : "--strip", ...(compress ? [] : ["--no-compress"])]);
}

function run(iprop, tool, directory) {
    const fixture = JSON.parse(fs.readFileSync(fixturePath, "utf8"));
    assert.equal(fixture.schema_version, 1);
    let generations = 0, traps = 0, compilerErrors = 0;
    const check = (file, cases, label) => {
        const bytes = fs.readFileSync(file);
        assert.equal(bytes.readUInt32LE(4), 0, "unversioned header");
        assert.equal(bytes.readUInt32LE(16), 0, "reserved header");
        for (const entry of cases) {
            assert.deepEqual(native(tool, file, entry.options, directory), entry.result, label + " native/0.8");
            if (iprop) assert.deepEqual(wasm(iprop, bytes, entry.options), entry.result, label + " WASM/0.8");
            ++generations;
        }
    };
    for (const program of fixture.programs) {
        for (const [source, hash] of Object.entries(program.sources))
            assert.equal(sha(fs.readFileSync(path.join(repo, source))), hash, "reference source " + source);
        const frozen = Buffer.from(program.binary_base64, "base64");
        assert.equal(sha(frozen), program.binary_sha256, "frozen binary digest");
        const file = path.join(directory, program.name + ".iprop");
        fs.writeFileSync(file, frozen);
        check(file, program.generations, program.name + " frozen bytes");
        const forms = program.name === "noise" ? ["scalar", "vector", "constant", "constant-vector"] : ["composition"];
        for (const form of forms) {
            let source = program.entry && path.join(repo, program.entry);
            if (program.name === "noise") {
                source = path.join(directory, "noise-" + form + ".ips");
                fs.writeFileSync(source, noiseSource(fixture.noise_vectors, form));
            }
            for (const optimize of [false, true]) for (const debug of [false, true])
                for (const compress of [false, true]) {
                    compile(tool, source, file, optimize, debug, compress);
                    if (program.name === "noise") {
                        const assembly = execFileSync(tool("ipdis"), [file], {encoding: "utf8"});
                        for (const op of ["noise", "fault", "noise.grad", "noise.fbm", "noise.cell", "noise.ridge", "warp"])
                            assert.equal(new RegExp("^\\s*" + op.replaceAll(".", "\\.") + "\\s*$", "m").test(assembly),
                                !form.startsWith("constant"), `${form} must exercise ${op} ${form.startsWith("constant") ? "folding" : "execution"}`);
                    }
                    check(file, program.generations, `${program.name}/${form}/${optimize}/${debug}/${compress}`);
                }
        }
    }

    // Explicit input bits bypass source-literal canonicalization, so NaN/Inf
    // and lattice boundaries reach the validated VM exactly as recorded.
    for (const entry of fixture.domains) {
        const base = path.join(directory, "domain");
        fs.writeFileSync(base + ".ipa", entry.assembly);
        execFileSync(tool("ipa"), [base + ".ipa", "-o", base + ".iprop"]);
        const bytes = fs.readFileSync(base + ".iprop");
        replaceFloatConstants(bytes, entry.float_bits);
        fs.writeFileSync(base + ".iprop", bytes);
        const png = base + ".png";
        fs.rmSync(png, {force: true});
        const actual = spawnSync(tool("ipgen"), [base + ".iprop", "--float-bits", "-o", png], {encoding: "utf8"});
        assert.equal(actual.signal, null, entry.name);
        if (entry.error) {
            assert.equal(actual.status, 1, entry.name);
            assert(actual.stderr.includes(entry.error), entry.name + ": " + actual.stderr);
            assert.equal(fs.existsSync(png), false, "failed generation published no PNG");
            if (iprop) assert.throws(() => iprop.generate(new Uint8Array(bytes), {}),
                error => error.message.includes(entry.error), entry.name);
            ++traps;
        } else {
            assert.equal(actual.status, 0, entry.name + ": " + actual.stderr);
            const values = JSON.parse(actual.stdout).outputs[0].values;
            assert.deepEqual(values, entry.values, entry.name + " native bits");
            if (iprop) assert.deepEqual(iprop.generate(new Uint8Array(bytes), {}).outputs[0].valueBits,
                entry.values, entry.name + " WASM bits");
            ++generations;
        }
    }
    for (const entry of fixture.constant_errors) {
        const source = path.join(directory, "bad-constant.ips"), file = source + ".iprop";
        fs.writeFileSync(source, `asset Invalid {size 1x1 const f32 bad=${entry.expression} draw{}}`);
        for (const optimize of [false, true]) {
            fs.rmSync(file, {force: true});
            const actual = spawnSync(tool("ipc"), [source, "-o", file, ...(optimize ? [] : ["--no-opt"])], {encoding: "utf8"});
            assert.equal(actual.status, 1, entry.expression);
            assert(actual.stderr.includes(entry.error), actual.stderr);
            assert.equal(fs.existsSync(file), false);
            ++compilerErrors;
        }
    }
    const contracts = JSON.parse(execFileSync(tool("ipc"), ["--describe-language"], {encoding: "utf8"}));
    for (const builtin of fixture.builtin_contracts) {
        const actual = contracts.builtins.find(b => b.name === builtin.name);
        assert(actual, "removed builtin " + builtin.name);
        for (const overload of builtin.overloads) {
            const match = actual.overloads.find(o => JSON.stringify(o.parameters) === JSON.stringify(overload.parameters));
            assert.deepEqual(match, overload, "changed 0.8 overload " + builtin.name);
        }
        if (builtin.variadic) assert.deepEqual(actual.variadic, builtin.variadic, builtin.name);
    }
    for (const [i, vector] of fixture.noise_vectors.entries())
        assert.equal(fixture.programs[0].generations[0].result.outputs[0].values[i].x, vector.expected_bits);
    for (const tie of fixture.worley_ties) {
        const features = worleyReference(tie.x, tie.y, tie.seed);
        assert.deepEqual(features.filter(p => p.bits === features[0].bits).map(p => [p.cx, p.cy]), tie.tied);
        assert.deepEqual([features[0].cx, features[0].cy], tie.winner);
        assert.equal(features[0].bits, tie.distance_bits);
    }
    return {generations, traps, compilerErrors, noiseVectors: fixture.noise_vectors.length,
        frozenPrograms: fixture.programs.length, wasm: Boolean(iprop)};
}

// Independent binary32 transcription of the published jitter/distance
// formulas. In 0.8 only F1 is observable; winner ownership at a tie becomes
// observable through cell_id in stage 02. Keep these witnesses for that gate.
function worleyReference(x, y, seed) {
    const f = Math.fround;
    const hash = value => {
        value ^= value >>> 16; value = Math.imul(value, 0x7feb352d);
        value ^= value >>> 15; value = Math.imul(value, 0x846ca68b);
        return (value ^ (value >>> 16)) >>> 0;
    };
    const features = [], buffer = Buffer.alloc(4);
    for (let cy = Math.floor(y) - 2; cy <= Math.floor(y) + 2; ++cy)
        for (let cx = Math.floor(x) - 2; cx <= Math.floor(x) + 2; ++cx) {
            const h = hash(seed ^ Math.imul(cx, 73856093) ^ Math.imul(cy, 19349663));
            const px = f(cx + f((h >>> 8) / 16777216));
            const py = f(cy + f((hash(h ^ 0x9e3779b9) >>> 8) / 16777216));
            const rx = f(px - x), ry = f(py - y);
            const distance = f(Math.sqrt(f(f(rx * rx) + f(ry * ry))));
            buffer.writeFloatLE(distance);
            features.push({cx, cy, distance, bits: buffer.readUInt32LE()});
        }
    return features.sort((a, b) => a.distance - b.distance || a.cy - b.cy || a.cx - b.cx);
}

module.exports = {run, noiseSource, native, compile, sha};

if (require.main === module) {
    const os = require("node:os");
    const directory = fs.mkdtempSync(path.join(os.tmpdir(), "iprop-compat-v08-"));
    const tools = path.resolve(process.argv[2] || "build/tools");
    const tool = name => path.join(tools, name + (process.platform === "win32" ? ".exe" : ""));
    try { console.log(JSON.stringify(run(null, tool, directory))); }
    finally { fs.rmSync(directory, {recursive: true, force: true}); }
}
